import { useEstacionamiento } from "../Context/EstacionamientoContext";

function Admin() {
const { espacios, cambiarEstado } = useEstacionamiento();

return (
<section>
<h1 style={{ fontSize: 28, fontWeight: 700, color: "#0f172a", marginBottom: 8 }}>
Administración de Espacios
</h1>
<p style={{ color: "#6b7280", marginBottom: 24 }}>
Mira el estado de cada espacio y cámbialo cuando lo necesites.
</p>

<table style={{ width: "100%", borderCollapse: "collapse", background: "white", borderRadius: 12, overflow: "hidden", boxShadow: "0 1px 4px rgba(0,0,0,0.08)" }}>
<thead>
<tr style={{ background: "#0f172a", color: "white" }}>
<th style={thStyle}>Espacio</th>
<th style={thStyle}>Estado</th>
<th style={thStyle}>Acción</th>
</tr>
</thead>
<tbody>
{espacios.map((e, i) => (
<tr key={e.id} style={{ background: i % 2 === 0 ? "#f8fafc" : "white" }}>
<td style={tdStyle}>Espacio {e.id}</td>
<td style={tdStyle}>
<span
style={{
padding: "4px 12px",
borderRadius: 20,
fontSize: 12,
fontWeight: 700,
background: e.estado === "libre" ? "#dcfce7" : "#fee2e2",
color: e.estado === "libre" ? "#166534" : "#991b1b"
}}
>
{e.estado === "libre" ? "Libre" : "Ocupado"}
</span>
</td>
<td style={tdStyle}>
<button
onClick={() => cambiarEstado(e.id)}
style={{
padding: "6px 16px",
borderRadius: 8,
border: "none",
cursor: "pointer",
fontWeight: 600,
fontSize: 13,
background: e.estado === "libre" ? "#fee2e2" : "#dcfce7",
color: e.estado === "libre" ? "#991b1b" : "#166534"
}}
>
{e.estado === "libre" ? "Marcar ocupado" : "Marcar libre"}
</button>
</td>
</tr>
))}
</tbody>
</table>
</section>
);
}

const thStyle = {
  padding: "14px 20px",
  textAlign: "left",
  fontSize: 13,
  fontWeight: 600,
  letterSpacing: 1
};

const tdStyle = {
  padding: "12px 20px",
  fontSize: 14,
  color: "#1f2937"
};

export default Admin;
